from pathlib import Path
import json
from reportlab.lib import colors
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Image, Table, TableStyle, PageBreak
ROOT=Path(__file__).resolve().parents[1]
def build():
    result_path=ROOT/"reports/analysis_results.json"
    if not result_path.exists(): raise FileNotFoundError("Run python src/analysis.py with the actual workbook before generating the report.")
    r=json.loads(result_path.read_text(encoding="utf-8")); d=r.get("dataset",{}); summary=r.get("summary",{})
    out=ROOT/"reports/final_report.pdf"; doc=SimpleDocTemplate(str(out),pagesize=letter,rightMargin=48,leftMargin=48,topMargin=42,bottomMargin=42)
    styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name="TitleWarm",parent=styles["Title"],textColor=colors.HexColor("#3B3028"),fontSize=24,leading=29,spaceAfter=10)); styles.add(ParagraphStyle(name="SectionWarm",parent=styles["Heading2"],textColor=colors.HexColor("#A85D45"),fontSize=13,spaceBefore=10,spaceAfter=5)); styles.add(ParagraphStyle(name="BodyWarm",parent=styles["BodyText"],textColor=colors.HexColor("#51463c"),fontSize=9,leading=13))
    story=[Paragraph("Retail Business Performance &amp; Profitability Analysis",styles["TitleWarm"]),Paragraph("Elevate Labs · Evidence-based internship project",styles["BodyWarm"]),Spacer(1,10),Paragraph("Objective",styles["SectionWarm"]),Paragraph("Identify profit-draining product areas, understand regional and seasonal performance, and assess demand signals using the source transactional workbook. No inventory metric is fabricated.",styles["BodyWarm"]),Paragraph("Dataset and method",styles["SectionWarm"]),Paragraph(f"Workbook: {d.get('source_file','unknown')}; worksheet row counts: {d.get('sheets',{})}; cleaned rows: {d.get('clean_rows','not reported')}; exact duplicates removed: {d.get('exact_duplicates_removed','not reported')}; rows removed for missing essential measures: {d.get('rows_removed_for_missing_required_fields','not reported')}. Date coverage: {d.get('date_min','not available')} to {d.get('date_max','not available')}. Python/Pandas/NumPy support cleaning and aggregation; SQLite/SQL provide reproducible query views; Seaborn/Matplotlib generate charts; Streamlit and Plotly power the interactive dashboard.",styles["BodyWarm"]),Paragraph("Key measured results",styles["SectionWarm"])]
    cells=[["Measure","Observed result"],["Total sales",f"{summary.get('total_sales','Not available')}"],["Total profit",f"{summary.get('total_profit','Not available')}"],["Weighted profit margin",f"{summary.get('profit_margin_pct','Not available')}%"]]
    table=Table(cells,colWidths=[2.5*inch,4.0*inch]); table.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#eee4d8")),("TEXTCOLOR",(0,0),(-1,-1),colors.HexColor("#3B3028")),("GRID",(0,0),(-1,-1),.4,colors.HexColor("#e4d9cd")),("PADDING",(0,0),(-1,-1),7)])); story.extend([table,Spacer(1,8)])
    for title,filename,explanation in [("Category profitability","category_profit.png","Category profit from transaction-level aggregation."),("Regional performance","regional_profit.png","Regional profit comparison."),("Monthly sales","monthly_sales.png","Sales trend grouped by observed order month.")]:
        p=ROOT/"reports/figures"/filename
        if p.exists(): story.extend([Paragraph(title,styles["SectionWarm"]),Image(str(p),width=6.25*inch,height=3.1*inch),Paragraph(explanation,styles["BodyWarm"])])
    story.extend([PageBreak(),Paragraph("Interpretation &amp; recommendations",styles["SectionWarm"]),Paragraph("Use the generated category, sub-category, regional, discount, seasonal, and product tables in reports/analysis_results.json and data/tableau_exports. Recommendations are limited to measured results; loss-making sub-categories prompt unit-economics and discount review, not automatic assortment removal. Discount association is descriptive, not causal.",styles["BodyWarm"]),Paragraph("Inventory limitation",styles["SectionWarm"]),Paragraph("The source schema inventory fields detected: "+str(d.get("inventory_fields",[]))+". Without inventory quantities, stock dates, lead times, and stockout periods, actual inventory turnover, inventory days, and inventory-days/profitability correlation cannot be calculated. Units per observed month is a sales-velocity proxy only; low sales do not prove overstock. Collect dated SKU-location stock snapshots, sales, receipts, stockout periods, and supplier lead times.",styles["BodyWarm"]),Paragraph("Currency &amp; Tableau",styles["SectionWarm"]),Paragraph("Financial values in this report retain source currency. Only if workbook evidence establishes USD may the configurable illustrative assumption ₹84/USD be applied; it is not a live exchange rate. Tableau-ready CSVs and a construction guide are provided. No Tableau workbook or public publication is claimed.",styles["BodyWarm"]),Paragraph("Conclusion",styles["SectionWarm"]),Paragraph("The analysis is reproducible from source records and its limits are explicit. Interpret performance findings in context of the actual workbook coverage, filtered population, and transaction grain.",styles["BodyWarm"])])
    doc.build(story); return out
if __name__=="__main__": print(build())
